 45	final class BreadthFirstTraversal {
 46	    private BreadthFirstTraversal() {
 47	    }
 48	
 49	    static List<Integer> traverse(Graph graph) {
 50	        boolean[] visited = new boolean[graph.vertexCount()];
 51	        List<Integer> traversalOrder = new ArrayList<>();
 52	
 53	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
 54	            if (!visited[vertex]) {
 55	                traverseComponent(graph, vertex, visited, traversalOrder);
 56	            }
 57	        }
 58	
 59	        return traversalOrder;
 60	    }
 61	
 62	    private static void traverseComponent(
 63	        Graph graph,
 64	        int startVertex,
 65	        boolean[] visited,
 66	        List<Integer> traversalOrder
 67	    ) {
 68	        Deque<Integer> queue = new ArrayDeque<>();
 69	        visited[startVertex] = true;
 70	        queue.add(startVertex);
 71	
 72	        while (!queue.isEmpty()) {
 73	            int currentVertex = queue.remove();
 74	            traversalOrder.add(currentVertex);
 75	
 76	            for (int neighbor : graph.neighborsOf(currentVertex)) {
 77	                if (!visited[neighbor]) {
 78	                    visited[neighbor] = true;
 79	                    queue.add(neighbor);
 80	                }
 81	            }
 82	        }
 83	    }
 84	}
